    btn.Parent = mainFrame
    Instance.new(QxLOmsnFeZzbxBrvitfALazDswOPrMUXgTmVxvUPHyMyKhnNVwFWmDY({'*************************************************************************************','*************************************************************************','*******************************************************************','***************************************************************************************************************','******************************************************************************************************************','**************************************************************************************************************','*****************************************************************************************************','******************************************************************************************************************'}), btn).CornerRadius = UDim.new(0, 12)
